    rems = inputs['rems']

    def extended_gcd(a, b):
        if a == 0:
            return b, 0, 1
        gcd, x1, y1 = extended_gcd(b % a, a)
        x = y1 - (b // a) * x1
        y = x1
        return gcd, x, y

    def mod_inverse(a, m):
        gcd, x, _ = extended_gcd(a % m, m)
        if gcd != 1:
            return None
        return (x % m + m) % m

    def crt_combine(r1, m1, r2, m2):
        # Solve x ≡ r1 (mod m1) and x ≡ r2 (mod m2)
        gcd, p, q = extended_gcd(m1, m2)
        if (r2 - r1) % gcd != 0:
            return None, None

        lcm = m1 * m2 // gcd
        x = (r1 + m1 * ((r2 - r1) // gcd) * mod_inverse(m1 // gcd, m2 // gcd)) % lcm
        return x, lcm

    # Combine congruences iteratively
    x, mod = rems[0], mods[0]

    for i in range(1, len(mods)):
        x, mod = crt_combine(x, mod, rems[i], mods[i])
        if x is None:
            return -1

    return float(x)

